-- ============================================================================
-- Brokerz - import your 10,000 access codes
-- ============================================================================
-- Run AFTER schema.sql. Safe to re-run: ON CONFLICT DO NOTHING means
-- re-running won't duplicate anything or reset codes that are already used.
--
-- Batched 500 per statement so no single statement is large enough to
-- upset the SQL editor.
-- ============================================================================























-- Verify: should report 10000 total.
select count(*) as total_codes,
       count(*) filter (where used_at is null) as unused
from access_codes;
